title "Sales Commission"
  instructions "
Commission is applied as marginal tiers:
- 3% on sales up to 10,000
- 5% on sales from 10,000 to 25,000
- 8% on sales above 25,000
"
  columns [
    column A
      width 140 {}
    column B
      width 120
      align "right" {}
    column C
      width 120
      align "right" {}
    column D
      width 120
      align "right" {}
