  cell A1
    text "Rep"
    font-weight "bold" {}
  cell B1
    text "Sales"
    font-weight "bold"
    align "right" {}
  cell C1
    text "Commission"
    font-weight "bold"
    align "right" {}
  cell D1
    text "Take-Home"
    font-weight "bold"
    align "right" {}
  cell A2
    text "Alice" {}
