    format "#,##0.00" {}
  cell A4
    text "Carol" {}
  cell B4
    text "32000"
    format "#,##0.00" {}
  cell C4
    text "=SUM(0.03*MIN(B4,10000), 0.05*MAX(MIN(B4,25000)-10000,0), 0.08*MAX(B4-25000,0))"
